#!/usr/bin/env bash
BASE="/opt/home-network-monitor"; source "$BASE/config.conf"; LOG="$BASE/logs/speed.csv"; NOW="$(date "+%Y-%m-%d %H:%M:%S")"; RESULT="$(timeout 180 /usr/local/bin/speedtest-go --server "$SPEEDTEST_SERVER_ID" --json 2>/dev/null || true)"; if [[ -z "$RESULT" ]]; then curl -fsS --max-time 15 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendMessage" -d "chat_id=${CHAT_ID}" --data-urlencode "text=⚠️ Home network speed test failed at ${NOW}" >/dev/null || true; exit 1; fi; DOWNLOAD_BYTES="$(jq -r ".servers[0].dl_speed // -1" <<< "$RESULT")"; LATENCY_NS="$(jq -r ".servers[0].latency // -1" <<< "$RESULT")"; SERVER="$(jq -r ".servers[0].sponsor // \"Unknown server\"" <<< "$RESULT")"; DOWNLOAD="$(awk "BEGIN{printf \"%.2f\",($DOWNLOAD_BYTES*8)/1000000}")"; LATENCY="$(awk "BEGIN{printf \"%.2f\",$LATENCY_NS/1000000}")"; [[ -f "$LOG" ]] || echo "timestamp,download_mbps,latency_ms,server" > "$LOG"; echo "\"$NOW\",$DOWNLOAD,$LATENCY,\"$SERVER\"" >> "$LOG"; LOW="$(awk "BEGIN{print ($DOWNLOAD<$DOWNLOAD_THRESHOLD_MBPS)}")"; HIGH="$(awk "BEGIN{print ($LATENCY>$LATENCY_THRESHOLD_MS)}")"; if [[ "$LOW" -eq 1 || "$HIGH" -eq 1 ]]; then curl -fsS --max-time 15 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendMessage" -d "chat_id=${CHAT_ID}" --data-urlencode "text=⚠️ Home network performance warning. Download: ${DOWNLOAD} Mbps. Latency: ${LATENCY} ms. Server: ${SERVER}. Time: ${NOW}" >/dev/null || true; fi
